import sys
from datetime import date, timedelta, datetime


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def clock(total):
    return f"{total // 60:02d}:{total % 60:02d}"


def parse_date(text):
    return datetime.strptime(text, "%Y-%m-%d").date()


def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "days":
            first = parse_date(parts[1])
            last = parse_date(parts[2])
            settings["days"] = (first, last)
        elif parts[0] == "hours":
            start = minutes(parts[1])
            end = minutes(parts[2])
            settings["hours"] = (start, end)
        elif parts[0] == "duration":
            settings["duration"] = int(parts[1])
        elif parts[0] == "buffer":
            settings["buffer"] = int(parts[1]) if len(parts) > 1 else 0
        elif parts[0] == "busy":
            who = parts[1]
            day = parse_date(parts[2])
            start = minutes(parts[3])
            end = minutes(parts[4])
            busy.setdefault((who, day.isoformat()), []).append((start, end))

    open_at, close_at = (minutes(t) for t in settings["hours"])
    need = int(settings["duration"])
    buffer = int(settings["buffer"])

    first_day = settings["days"][0]
    last_day = settings["days"][1]

    current_day = first_day
    while current_day <= last_day:
        day_str = current_day.isoformat()
        if current_day.weekday() >= 5:  # Skip weekends (5=Saturday, 6=Sunday)
            current_day += timedelta(days=1)
            continue

        taken = []
        if ("A", day_str) in busy:
            taken.extend(busy[("A", day_str)])
        if ("B", day_str) in busy:
            taken.extend(busy[("B", day_str)])

        # Sort busy intervals by start time
        taken.sort(key=lambda x: x[0])

        merged_busy = []
        if taken:
            merged_busy = [taken[0]]
            for b in taken[1:]:
                last = merged_busy[-1]
                if b[0] <= last[1]:
                    # Overlapping or adjacent: merge
                    merged_busy[-1] = (last[0], max(last[1], b[1]))
                else:
                    merged_busy.append(b)

        # Generate free slots
        slots = []
        cursor = open_at
        for start_b, end_b in merged_busy:
            if cursor - start_b >= need:
                slots.append((clock(cursor), clock(start_b)))
            cursor = end_b
        if close_at - cursor >= need:
            slots.append((clock(cursor), clock(close_at)))

        # Filter slots by duration and format output
        formatted = []
        for s_start, s_end in slots:
            s_duration = (int(s_end.split(":")[0]) * 60 + int(s_end.split(":")[1])) - (
                int(s_start.split(":")[0]) * 60 + int(s_start.split(":")[1])
            )
            if s_duration >= need:
                formatted.append(f"{s_start}-{s_end}")

        output = day_str
        if formatted:
            output += " " + " ".join(formatted)
        else:
            output += " none"

        print(output)

        current_day += timedelta(days=1)


if __name__ == "__main__":
    main()
